<?php
declare(strict_types=1);
function requestInput(): array { $raw=file_get_contents('php://input'); $data=json_decode($raw ?: '',true); return is_array($data)?$data:[]; }
function jsonResponse(bool $success,string $message='',int $status=200,array $extra=[]): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode(array_merge(['success'=>$success,'message'=>$message],$extra),JSON_UNESCAPED_UNICODE); exit; }
function bearerToken(): string { $header=(string)($_SERVER['HTTP_X_BASIS_SESSION']??$_SERVER['HTTP_AUTHORIZATION']??''); if($header==='' && function_exists('getallheaders')) { $headers=getallheaders()?:[]; $header=(string)($headers['X-Basis-Session']??$headers['x-basis-session']??$headers['Authorization']??$headers['authorization']??''); } if(preg_match('/^Bearer\s+([a-f0-9]{64})$/i',$header,$match)) return $match[1]; return preg_match('/^[a-f0-9]{64}$/i',$header)?$header:''; }
function authenticatedUser(PDO $pdo, bool $allowPasswordChange=false): array { $token=bearerToken(); if($token!=='') { $stmt=$pdo->prepare('SELECT u.id,u.role,u.status,u.must_change_password FROM auth_sessions a JOIN users u ON u.id=a.user_id WHERE a.token_hash=? AND a.expires_at>CURRENT_TIMESTAMP'); $stmt->execute([hash('sha256',$token)]); $user=$stmt->fetch(); if(!$user || $user['status']!=='ACTIVE') jsonResponse(false,'Your sign-in has expired. Please sign in again.',401); if(!$allowPasswordChange && (int)$user['must_change_password']===1) jsonResponse(false,'Change your temporary password before continuing.',428); return $user; } if(session_status()!==PHP_SESSION_ACTIVE) session_start(); $id=(int)($_SESSION['user_id']??0); if(!$id) jsonResponse(false,'Please sign in.',401); $stmt=$pdo->prepare('SELECT id,role,status,must_change_password FROM users WHERE id=?'); $stmt->execute([$id]); $user=$stmt->fetch(); if(!$user || $user['status']!=='ACTIVE') jsonResponse(false,'Account is unavailable.',403); if(!$allowPasswordChange && (int)$user['must_change_password']===1) jsonResponse(false,'Change your temporary password before continuing.',428); return $user; }
function requireUser(PDO $pdo, array $roles=[]): array { $user=authenticatedUser($pdo); if($roles && !in_array($user['role'],$roles,true)) jsonResponse(false,'You do not have permission for this action.',403); return $user; }
